with cleaned as (select *, substring(status, 1, 3) as status_prefix from subscriptions where month(end_date) in (2, 7, 11)) select *, rank() over (partition by customer_id order by monthly_fee nulls first) as monthly_fee_rank, sum(monthly_fee) over w_recent as cumulative_monthly_fee, avg(monthly_fee) over (partition by customer_id order by start_date, id rows between 6 preceding and current row) as monthly_fee_avg_6 from cleaned window w_recent as (partition by customer_id order by start_date, id rows between unbounded preceding and current row);
